        this.M = M;
        this.v = Arrays.copyOf(v,v.length); // > Java-5
    }



    @Override
    public String toString() {
        StringBuffer sb = new StringBuffer("Dimension( " + d + ", ");
        if (v == null) {
            sb.append("" + S + ", " + M + " )");
            return sb.toString();
        }
        String[] s = new String[S.size()];
        int j = 0;
        for (Integer i : S) {
            s[j] = v[i];
            j++;
        }
        sb.append(Arrays.toString(s) + ", ");
        sb.append("[ ");
        boolean first = true;
        for (Set<Integer> m : M) {
            if (first) {
                first = false;
            } else {
                sb.append(", ");
            }
            s = new String[m.size()];
            j = 0;
            for (Integer i : m) {
                s[j] = v[i];
                j++;
            }
            sb.append(Arrays.toString(s));
        }
        sb.append(" ] )");
        return sb.toString();
    }
}

